  taste_tags = excluded.taste_tags,
  ingredient_tags = excluded.ingredient_tags,
  allergen_tags = excluded.allergen_tags,
  dietary_tags = excluded.dietary_tags,
  spicy_level = excluded.spicy_level,
  image_type = excluded.image_type,
  ai_suggested = excluded.ai_suggested,
  confirmed_by_restaurant = excluded.confirmed_by_restaurant;

