with demo_users as (
  select unnest(array[
    '10000000-0000-0000-0000-000000000001'::uuid,
    '10000000-0000-0000-0000-000000000003'::uuid,
    '10000000-0000-0000-0000-000000000004'::uuid,
    '10000000-0000-0000-0000-000000000005'::uuid,
    '10000000-0000-0000-0000-000000000006'::uuid,
    '10000000-0000-0000-0000-000000000007'::uuid
  ]) as user_id
),
demo_restaurants as (
  select unnest(array[
    '20000000-0000-0000-0000-000000000001'::uuid,
    '20000000-0000-0000-0000-000000000002'::uuid,
    '20000000-0000-0000-0000-000000000003'::uuid,
    '20000000-0000-0000-0000-000000000004'::uuid,
    '20000000-0000-0000-0000-000000000005'::uuid
  ]) as restaurant_id
),
viewed_events as (
  select
    gen_random_uuid() as id,
    (array(select user_id from demo_users))[1 + ((gs - 1) % 6)] as user_id,
    case when gs % 7 = 0 then '30000000-0000-0000-0000-000000000001'::uuid else null::uuid end as group_id,
    case
      when gs <= 140 then '20000000-0000-0000-0000-000000000001'::uuid
      else (array(select restaurant_id from demo_restaurants))[1 + ((gs - 141) % 5)]
    end as restaurant_id,
    'viewed'::text as action,
    array[]::text[] as reject_reasons,
    null::numeric as match_score,
    jsonb_build_object(
      'demo_seed', 'true',
      'source', 'demo_funnel',
      'query', case
        when gs % 5 = 0 then 'spicy local food no pork'
        when gs % 5 = 1 then 'quiet mountain view local restaurant'
        when gs % 5 = 2 then 'vegetarian local food'
        when gs % 5 = 3 then 'seafood photo spot'
        else 'family friendly Thai food'
      end
    ) as query_context,
    '{}'::jsonb as score_breakdown,
    now() - ((gs % 29)::text || ' days')::interval - ((gs % 11)::text || ' hours')::interval as created_at
  from generate_series(1, 210) as gs
),
selected_events as (
  select
    gen_random_uuid() as id,
    (array(select user_id from demo_users))[1 + ((gs - 1) % 6)] as user_id,
    case when gs % 5 = 0 then '30000000-0000-0000-0000-000000000001'::uuid else null::uuid end as group_id,
    case
      when gs <= 52 then '20000000-0000-0000-0000-000000000001'::uuid
      else (array(select restaurant_id from demo_restaurants))[1 + ((gs - 53) % 5)]
    end as restaurant_id,
    'selected'::text as action,
    array[]::text[] as reject_reasons,
    (78 + (gs % 18))::numeric as match_score,
    jsonb_build_object('demo_seed', 'true', 'source', 'demo_selection') as query_context,
    jsonb_build_object(
      'menuScore', 42 + (gs % 8),
      'restaurantScore', 22 + (gs % 7),
      'learnedPreferenceScore', 8 + (gs % 4)
    ) as score_breakdown,
    now() - ((gs % 28)::text || ' days')::interval - ((gs % 8)::text || ' hours')::interval as created_at
  from generate_series(1, 78) as gs
),
skipped_events as (
  select
    gen_random_uuid() as id,
    (array(select user_id from demo_users))[1 + ((gs - 1) % 6)] as user_id,
    case when gs % 6 = 0 then '30000000-0000-0000-0000-000000000001'::uuid else null::uuid end as group_id,
    case
      when gs <= 32 then '20000000-0000-0000-0000-000000000001'::uuid
      else (array(select restaurant_id from demo_restaurants))[1 + ((gs - 33) % 5)]
    end as restaurant_id,
    'skipped'::text as action,
    case gs % 6
      when 0 then array['not_safe_allergy']
      when 1 then array['too_far']
      when 2 then array['menu_hard_to_understand']
      when 3 then array['too_expensive']
      when 4 then array['parking_not_enough']
      else array['not_enough_vegetarian_options']
    end as reject_reasons,
    (55 + (gs % 18))::numeric as match_score,
    jsonb_build_object(
      'demo_seed', 'true',
      'source', 'demo_skip',
      'selectedBubble', case gs % 6
        when 0 then 'not_safe_allergy'
        when 1 then 'too_far'
        when 2 then 'menu_hard_to_understand'
        when 3 then 'too_expensive'
        when 4 then 'parking_not_enough'
        else 'not_enough_vegetarian_options'
      end
    ) as query_context,
    jsonb_build_object(
      'menuScore', 25 + (gs % 8),
      'restaurantScore', 17 + (gs % 6),
      'riskPenalty', 8 + (gs % 9)
    ) as score_breakdown,
    now() - ((gs % 27)::text || ' days')::interval - ((gs % 10)::text || ' hours')::interval as created_at
  from generate_series(1, 56) as gs
)
insert into public.match_histories (
  id,
  user_id,
  group_id,
  restaurant_id,
  action,
  reject_reasons,
  match_score,
  query_context,
  score_breakdown,
  created_at
)
select * from viewed_events
union all
select * from selected_events
union all
select * from skipped_events;

